# http { } block (e.g. /etc/nginx/conf.d/ai-bots.conf)
map $http_user_agent $is_ai_bot {
    default 0;
    "~*(GPTBot|ClaudeBot|PerplexityBot)" 1;   # "GPTBot" "ClaudeBot" "PerplexityBot"
}
# rate-limit key: an empty key for AI bots = the limit is not applied
map $is_ai_bot $ai_limit_key {
    0 $binary_remote_addr;
    1 "";
}
limit_req_zone $ai_limit_key zone=perip:10m rate=10r/s;

# server { } block — exempt AI bots from your existing UA block:
set $block_ua 0;
if ($http_user_agent ~* "(bot|crawl|spider|scrape)") { set $block_ua 1; }   # ← your existing rule
if ($is_ai_bot = 1) { set $block_ua 0; }
if ($block_ua = 1) { return 403; }

// AI bots do not run JavaScript; https://botsim.example.com/uygulama must return its content in the first HTML.
// Next.js (App Router) — render the page as a Server Component:
// app/product/[slug]/page.tsx
export const revalidate = 3600; // ISR: static regeneration once an hour

export default async function ProductPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const product = await getProduct(slug); // fetch the data on the server (NOT useEffect + fetch)
  return (
    <article>
      <h1>{product.name}</h1>
      <p>{product.summary}</p>
      <ProductSpecsTable specs={product.specs} />
    </article>
  );
}

